var M, R, N, L = 5; // max radius, normal radius, num points, length between points

function setup() {
	createCanvas(windowWidth, windowHeight);
	describe("noisy star");
	frameRate(30);

	M = ~~max(width, height) * 0.45; // max dia
	R = M / 5;                      // normal dia
	const CIRC = TWO_PI * R;            // circumference 
	N = ~~(CIRC / L);               // num of points

	FG = color("deeppink");
	BG = color(4, 4, 12);

	background(BG);
	strokeWeight(2);
	stroke(FG);
	noFill();

	loop();
}

function draw() {
	background(BG);
	translate(width/2, height/2);

	const t = frameCount/30;
	rotate(noise(t/10));
	// circle(0, 0, S);
	beginShape();
	for (let i = 0; i < N; i++) {
		const f = i/N;
		const a = TAU * f;
		const cos_angle = cos(a);
		const sin_angle = sin(a);
		const n = noise(10 + cos_angle * 5, 30 + sin_angle * 5, t);
		const EVERY_SECOND = i % 2 === 0;
		const DR = EVERY_SECOND ? 0 : (1 - n * n) * (M-R)
		const DX = EVERY_SECOND ? cos_angle * R * n : 0;
		const DY = EVERY_SECOND ? sin_angle * R * n : 0;
		const x = DX + cos_angle * (R + DR);
		const y = DY + sin_angle * (R + DR);
		vertex(x, y);
	}
	endShape(CLOSE);

	// // noLoop() removed for animation
}
